// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.edge;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.row;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFanOutFactsTest.StatsSource;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativePlanExecutionProfile.Mode;
import org.junit.jupiter.api.Test;

/**
 * The execution profile prices MINUS, EXISTS, OPTIONAL and a join's filters as their cursors run them, in sequential,
 * batch and kernel form.
 */
class LmdbNativePlanExecutionProfileTest {

	private static final long P1 = 1L, P2 = 2L, P3 = 3L;
	private static final int S = 0, A = 1, B = 2;

	private static StatsSource stats() {
		return new StatsSource(100_000L).predicate(P1, 3D, 3_000L).predicate(P2, 3D, 3_000L).predicate(P3, 3D, 3_000L);
	}

	private static PatternPlan star() {
		return edge(S, P1, A, 9_000D);
	}

	private static MultiJoinPlan compositeRight() {
		// ?s p2 ?b . ?b p3 ?a' (a fresh slot would need a wider layout; the chain reuses A as a free slot)
		return new MultiJoinPlan(new SlotPlan[] { edge(S, P2, B, 9_000D), edge(B, P3, A, 9_000D) },
				new MaskedFilter[0]);
	}

	private static LmdbNativeCostVector prefix(RowState row) {
		return LmdbNativeCostVectors.pattern(star(), row, 0L);
	}

	private static LmdbNativeCostVector probe(RowState row) {
		return LmdbNativeCostVectors.pattern(edge(S, P2, B, 9_000D), row, 1L << S);
	}

	private static NativeBooleanFilter acceptAll() {
		return new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState row) {
				return true;
			}

			@Override
			public void close() {
			}
		};
	}

	@Test
	void aMinusWhoseRightSideAssuresTheSharedSlotIsAFirstMatchPerRowWithAMemoLookup() {
		RowState row = row(stats());
		MinusPlan minus = new MinusPlan(star(), compositeRight(), 1L << S);
		LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.profile(minus, row, 0L, Mode.SEQUENTIAL);
		// 9000 left rows: each opens the two patterns of the right side and reads their first record
		assertThat(quote.expected(Feature.BRANCH_OPEN)).isEqualTo(2D * 9_000D);
		assertThat(quote.expected(Feature.INDEX_SEEK))
				.isEqualTo(prefix(row).expected(Feature.INDEX_SEEK)
						+ 2D * 9_000D * probe(row).expected(Feature.INDEX_SEEK));
		assertThat(quote.expected(Feature.SCANNED_ROW))
				.isEqualTo(prefix(row).expected(Feature.SCANNED_ROW) + 2D * 9_000D);
		assertThat(quote.expected(Feature.MEMBERSHIP_TEST)).isEqualTo(9_000D);
	}

	@Test
	void aMinusWhoseRightSideDoesNotAssureTheSharedSlotRunsTheWholeRightSidePerRow() {
		RowState row = row(stats());
		// a UNION whose second arm never binds ?s does not assure the shared slot: the right side is evaluated
		// independently and compared per left row
		UnionPlan union = new UnionPlan(edge(S, P2, B, 9_000D), edge(A, P3, B, 9_000D));
		MinusPlan minus = new MinusPlan(star(), union, 1L << S);
		LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.profile(minus, row, 0L, Mode.SEQUENTIAL);
		assertThat(quote.expected(Feature.SCANNED_ROW))
				.isGreaterThanOrEqualTo(prefix(row).expected(Feature.SCANNED_ROW) + 9_000D * 18_000D);
	}

	@Test
	void aJoinsFilterIsChargedAtItsDepth() {
		RowState row = row(stats());
		MultiJoinPlan join = new MultiJoinPlan(new SlotPlan[] { star(), edge(S, P2, B, 9_000D) },
				new MaskedFilter[] { new MaskedFilter(acceptAll(), 1L << A) });
		LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.profile(join, row, 0L, Mode.SEQUENTIAL);
		// the chain's 9000 and 27000 interpreted rows, then the filter: it reads ?a only, so it runs once per prefix
		// row after the first pattern (9000), not per joined row (27000)
		assertThat(quote.expected(Feature.INTERPRETED_ROW)).isEqualTo(9_000D + 27_000D + 9_000D);
		MultiJoinPlan late = new MultiJoinPlan(new SlotPlan[] { star(), edge(S, P2, B, 9_000D) },
				new MaskedFilter[] { new MaskedFilter(acceptAll(), 1L << B) });
		assertThat(LmdbNativePlanExecutionProfile.profile(late, row, 0L, Mode.SEQUENTIAL)
				.expected(Feature.INTERPRETED_ROW)).isEqualTo(9_000D + 27_000D + 27_000D);
	}

	@Test
	void anExistsOverAnUnpricedSubplanIsChargedAsASweepPerRow() {
		RowState row = row(stats());
		SlotPlan unpriced = new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				throw new UnsupportedOperationException();
			}

			@Override
			public long producedMask() {
				return 1L << B;
			}
		};
		FilterPlan filter = new FilterPlan(star(), new ExistsFilter(unpriced), 1L << S);
		LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.profile(filter, row, 0L, Mode.SEQUENTIAL);
		assertThat(quote.expected(Feature.SCANNED_ROW))
				.isGreaterThanOrEqualTo(prefix(row).expected(Feature.SCANNED_ROW) + 9_000D * 50_000D);
	}

	@Test
	void theBatchFormConvertsEveryLeftRowOfAMinus() {
		RowState row = row(stats());
		MinusPlan minus = new MinusPlan(star(), compositeRight(), 1L << S);
		LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.profile(minus, row, 0L, Mode.BATCH);
		// the batch cursor wraps the row cursor: an interpreted row and a batch row per converted left row on top
		// of the batch rows the prefix produces
		assertThat(quote.expected(Feature.INTERPRETED_ROW)).isEqualTo(9_000D);
		assertThat(quote.expected(Feature.BATCH_ROW)).isEqualTo(9_000D + 9_000D);
	}

	@Test
	void theKernelWitnessIsStrictlyBelowTheSequentialProbe() {
		RowState row = row(stats());
		MinusPlan minus = new MinusPlan(star(), compositeRight(), 1L << S);
		LmdbNativeCostVector sequential = LmdbNativePlanExecutionProfile.profile(minus, row, 0L, Mode.SEQUENTIAL);
		LmdbNativeCostVector kernel = LmdbNativePlanExecutionProfile.profile(minus, row, 0L, Mode.KERNEL);
		assertThat(kernel.expected(Feature.BRANCH_OPEN)).isZero();
		assertThat(kernel.expected(Feature.MEMBERSHIP_TEST)).isZero();
		assertThat(kernel.expected(Feature.INDEX_SEEK)).isLessThanOrEqualTo(sequential.expected(Feature.INDEX_SEEK));
		assertThat(kernel.expected(Feature.INDEX_SEEK))
				.isEqualTo(prefix(row).expected(Feature.INDEX_SEEK) + 2D * 9_000D);
	}
}
